#include <stdio.h>
#include <stdlib.h>

int cmp(const void *a, const void *b) {
    return (*(int *) a) - (*(int *) b);
}

int main() {
    int nums_size;
    scanf("%d", &nums_size);

    int nums[nums_size];
    for (int i = 0; i < nums_size; i++) {
        scanf("%d", &nums[i]);
    }

    int n;
    scanf("%d", &n);

    qsort(nums, nums_size, sizeof(int), cmp);

    int ans = 0;
    for (int i = 0; i < nums_size; i++) {
        for (int j = nums_size - 1; j >= i + 1; j--) {
            int sum = nums[i] + nums[j];

            if (sum == n) ans++;
            else if (sum < n) break;
        }
    }

    printf("%d\n", ans);

    return 0;
}
